-- # Lernfeld 5: Cyberphysische Systeme > ## Programmierung > - Programmiersprachen > - Frameworks

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Framework die Entwicklungszeit eines Projekts unabhängig von der Programmiersprache verkürzen?', 2, '[{"text": "Ja", "correct": true, "because": "Frameworks bieten vorgefertigte Strukturen"}, {"text": "Nein", "correct": false, "because": "Effizienz ist sprachübergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind alle Frameworks für jede Programmiersprache verfügbar?', 2, '[{"text": "Nein", "correct": true, "because": "Frameworks sind sprachspezifisch entwickelt"}, {"text": "Ja", "correct": false, "because": "Kompatibilität ist begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Frameworks die Wartbarkeit von Code verschlechtern, wenn sie schlecht gewählt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Unpassende Frameworks erhöhen Komplexität"}, {"text": "Nein", "correct": false, "because": "Wartbarkeit kann leiden"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Verwendung eines Frameworks immer effizienter als das Schreiben von purem Code?', 2, '[{"text": "Nein", "correct": true, "because": "Kleine Projekte profitieren oft nicht"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Framework die Wahl der Programmiersprache für ein Projekt einschränken?', 2, '[{"text": "Ja", "correct": true, "because": "Frameworks sind an Sprachen gebunden"}, {"text": "Nein", "correct": false, "because": "Einschränkung ist real"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Framework ist primär mit der Programmiersprache Python verbunden?', 2, '[{"text": "Django", "correct": true, "because": "Django ist ein bekanntes Python-Framework"}, {"text": "Spring", "correct": false, "because": "Spring ist für Java"}, {"text": "Angular", "correct": false, "because": "Angular ist für JavaScript"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Auswahl eines Frameworks für eine Webanwendung am kritischsten?', 3, '[{"text": "Community-Unterstützung", "correct": true, "because": "Langfristige Wartung und Hilfe"}, {"text": "Kosten", "correct": false, "because": "Meist Open Source"}, {"text": "Farbe der Dokumentation", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework wird häufig für die Entwicklung von Java-Anwendungen verwendet?', 2, '[{"text": "Spring", "correct": true, "because": "Spring ist ein Standard für Java"}, {"text": "Laravel", "correct": false, "because": "Laravel ist für PHP"}, {"text": "React", "correct": false, "because": "React ist für JavaScript"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework unterscheidet sich durch seine Fokussierung auf Single-Page-Anwendungen?', 2, '[{"text": "React", "correct": true, "because": "React ist darauf spezialisiert"}, {"text": "Django", "correct": false, "because": "Django ist serverseitig"}, {"text": "Ruby on Rails", "correct": false, "because": "Full-Stack-Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt macht die Wahl eines Frameworks von der Programmiersprache abhängig?', 2, '[{"text": "Syntax-Kompatibilität", "correct": true, "because": "Framework muss zur Sprache passen"}, {"text": "Teamgröße", "correct": false, "because": "Sekundär"}, {"text": "Projektbudget", "correct": false, "because": "Weniger relevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Frameworks sind für JavaScript-basierte Frontend-Entwicklung geeignet?', 4, '[{"text": "React", "correct": true, "because": "Fokussiert auf UI"}, {"text": "Vue.js", "correct": true, "because": "Flexibel und leicht"}, {"text": "Django", "correct": false, "because": "Python-basiert"}, {"text": "Angular", "correct": true, "because": "Full-Featured-Framework"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Auswahl eines Frameworks?', 3, '[{"text": "Projektanforderungen", "correct": true, "because": "Bestimmt Funktionalität"}, {"text": "Teamkompetenz", "correct": true, "because": "Erfahrung zählt"}, {"text": "Farbauswahl der IDE", "correct": false, "because": "Irrelevant"}, {"text": "Community-Größe", "correct": true, "because": "Unterstützung wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frameworks sind für serverseitige Entwicklung bekannt?', 3, '[{"text": "Django", "correct": true, "because": "Python-Server-Framework"}, {"text": "Spring", "correct": true, "because": "Java-Server-Framework"}, {"text": "React", "correct": false, "because": "Clientseitig"}, {"text": "Laravel", "correct": true, "because": "PHP-Server-Framework"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Frameworks bei der Programmierung?', 4, '[{"text": "Schnellere Entwicklung", "correct": true, "because": "Vorgefertigte Strukturen"}, {"text": "Bessere Wartbarkeit", "correct": true, "because": "Standardisierte Ansätze"}, {"text": "Höhere Hardwarekosten", "correct": false, "because": "Nicht zutreffend"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Code wird wiedergenutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können bei der Verwendung von Frameworks auftreten?', 3, '[{"text": "Lernkurve", "correct": true, "because": "Zeit für Einarbeitung nötig"}, {"text": "Abhängigkeit", "correct": true, "because": "Updates können Probleme bringen"}, {"text": "Einfacher Debugging", "correct": false, "because": "Eher komplizierter"}, {"text": "Eingeschränkte Flexibilität", "correct": true, "because": "Vorgaben limitieren"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Frameworks sind für jede Programmiersprache verfügbar. b) Die Wahl eines Frameworks kann die Projektkosten senken.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Nicht alle Sprachen, Kostenreduktion möglich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Auswahl eines Frameworks hängt von der Zielplattform ab. b) Frameworks machen Entwickler unabhängig von der Sprache.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Plattform wichtig, Sprache bindend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Frameworks erhöhen immer die Entwicklungsgeschwindigkeit. b) Teamkompetenz ist bei der Framework-Auswahl irrelevant.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Nicht immer schneller, Kompetenz entscheidend"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Django ist ein Framework für Python. b) Frameworks sind für kleine Projekte ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Django für Python, Größe flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Wahl eines Frameworks kann die Wartbarkeit verbessern. b) Alle Frameworks sind Open Source.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartbarkeit steigt, nicht alle Open Source"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

